class Node:
    def __init__(self, value, nxt=None):
        self.value = value
        self.nxt = nxt

def push(head, value):
    return Node(value, head)

def to_list(head):
    out = []
    while head is not None:
        out.append(head.value)
        head = head.nxt
    return out

def search(head, target):
    index = 0
    while head is not None:
        if head.value == target:
            return index
        head = head.nxt
        index += 1
    return -1

def reverse(head):
    prev = None
    while head is not None:
        nxt = head.nxt
        head.nxt = prev
        prev = head
        head = nxt
    return prev

head = None
for value in (4, 3, 2, 1):
    head = push(head, value)
assert to_list(head) == [1, 2, 3, 4]
assert search(head, 3) == 2 and search(head, 9) == -1
assert to_list(reverse(head)) == [4, 3, 2, 1]
built = None
for value in (8, 5, 8, 2):
    built = push(built, value)
assert to_list(built) == [2, 8, 5, 8] and search(built, 5) == 2
print(search(built, 5), to_list(built))
